input.content:
package piglatin

import "strings"

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = translate(word)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func translate(word string) string {
	if len(word) == 0 {
		return word
	}

	// Rule 1: word begins with a vowel, or starts with "xr" or "yt".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find the first vowel or 'y' (Rule 4: 'y' acts as a vowel after
	// a consonant cluster). Everything before it is the consonant prefix.
	i := 0
	for i < len(word) && !isVowel(word[i]) && word[i] != 'y' {
		i++
	}

	// Rule 3: if the prefix ends in "qu", move the "u" along with it.
	if i > 0 && word[i-1] == 'q' && word[i] == 'u' {
		i++
	}

	// Rule 2: move the consonant prefix to the end and add "ay".
	return word[i:] + word[:i] + "ay"
}

